	ObservedArgumentError[2] := _comparison.ArgumentError;
	CasePassed[2] := (_comparison.Passed = FALSE) AND (_comparison.ArgumentError = TRUE);
	CasePassed[2] := CasePassed[2] AND (LEN(_comparison.DiagnosticSuffix) > 0);
	_comparison := _underTest.CompareAnyForQualification(ExpectedData := ADR(_bytes[1]), ActualData := ADR(_bytes[1]), ExpectedSize := -1, ActualSize := 1, ExpectedClass := TO_DINT(IBaseLibrary.TypeClass.TYPE_BYTE), ActualClass := TO_DINT(IBaseLibrary.TypeClass.TYPE_BYTE));
