	_comparison := _underTest.CompareAnyForQualification(ExpectedData := ADR(_bytes[1]), ActualData := ADR(_bytes[1]), ExpectedSize := 1, ActualSize := 1, ExpectedClass := TO_DINT(IBaseLibrary.TypeClass.TYPE_BYTE), ActualClass := TO_DINT(IBaseLibrary.TypeClass.TYPE_WORD));
	ObservedPassed[9] := _comparison.Passed;
