	CasePassed[9] := (_comparison.Passed = FALSE) AND (_comparison.ArgumentError = FALSE);
	_comparison := _underTest.CompareAnyForQualification(ExpectedData := ADR(_bytes[1]), ActualData := ADR(_bytes[1]), ExpectedSize := 4, ActualSize := 4, ExpectedClass := TO_DINT(IBaseLibrary.TypeClass.TYPE_WSTRING), ActualClass := TO_DINT(IBaseLibrary.TypeClass.TYPE_WSTRING));
	ObservedPassed[10] := _comparison.Passed;
	ObservedArgumentError[10] := _comparison.ArgumentError;
	CasePassed[10] := (_comparison.Passed = FALSE) AND (_comparison.ArgumentError = TRUE);
	CasePassed[10] := CasePassed[10] AND (LEN(_comparison.DiagnosticSuffix) > 0);
	GuardIntact := (_bytes[0] = 16#AA) AND (_bytes[1] = 65) AND (_bytes[2] = 66) AND (_bytes[3] = 67) AND (_bytes[4] = 68) AND (_bytes[5] = 0) AND (_bytes[6] = 16#BB);
	OraclePass := GuardIntact;
	FOR _i := 1 TO 10 DO OraclePass := OraclePass AND CasePassed[_i]; END_FOR
	Done := TRUE;
END_IF

InterfaceAsPlainText.xhtml:
PROGRAM PRG_Qualification
VAR_OUTPUT
	Done : BOOL;
	OraclePass : BOOL;
	GuardIntact : BOOL;
	CasePassed : ARRAY[1..10] OF BOOL;
	ObservedPassed : ARRAY[1..10] OF BOOL;
	ObservedArgumentError : ARRAY[1..10] OF BOOL;
END_VAR
VAR
	_underTest : FB_TestSuite;
	_bytes : ARRAY[0..6] OF BYTE := [16#AA, 65, 66, 67, 68, 0, 16#BB];
	_comparison : ST_CoUnitComparisonResult;
	_i : UINT;
END_VAR
